import {getUtf8StringLength} from '@github-ui/text'
import {onInput} from '@github-ui/onfocus'

const SCREEN_READER_UPDATE_DELAY = 500
const pluralize = (count: number) => {
  return count === 1 ? 'character' : 'characters'
}

const buildCharacterCountText = (valueLength: number, limit: number) => {
  if (valueLength > limit) {
    const amountOver = valueLength - limit
    return `${amountOver} ${pluralize(amountOver)} over.`
  } else {
    const remaining = limit - valueLength
    return `${remaining} ${pluralize(remaining)} remaining.`
  }
}

const showRemainingCharacterCount = (value: string, limit: number, field: HTMLTextAreaElement) => {
  const buttonElement: HTMLButtonElement | null = document.querySelector('button.js-ignored-user-note-submit')
  const liveRegion = document.getElementById('ignored-user-character-count-sr')
  const formControl = field.closest('.FormControl')
  // Make sure the button is disabled if there is more than 250 characters
  const validationMessage = formControl?.querySelector('.FormControl-inlineValidation')
  const validationMessageSibling = validationMessage?.nextElementSibling
  const hasCharactersRemainingElement = validationMessageSibling?.classList.contains(
    'js-ignored-user-note-characters-remaining',
  )
  const valueLength = getUtf8StringLength(value)
  const isOverLimit = valueLength > limit

  // Update validation state on the textarea
  field.setAttribute('aria-invalid', isOverLimit ? 'true' : 'false')
  field.setAttribute('invalid', isOverLimit ? 'true' : '')

  if (validationMessage) {
    if (isOverLimit) {
      // eslint-disable-next-line i18n-text/no-en
      validationMessage.textContent = `Note exceeds the maximum length of ${limit} characters.`
      validationMessage.setAttribute('aria-live', 'assertive')
      validationMessage.removeAttribute('hidden')

      if (buttonElement) {
        buttonElement.setAttribute('aria-disabled', 'true')
        buttonElement.onclick = (e: Event) => e.preventDefault()
        buttonElement.classList.add('disabled')
      }
    } else {
      validationMessage.setAttribute('hidden', '')
      validationMessage.setAttribute('aria-live', 'polite')

      if (buttonElement) {
        buttonElement.setAttribute('aria-disabled', '')
        buttonElement.onclick = null
        buttonElement.classList.remove('disabled')
      }
    }
  }

  // If the element already exists, update the text. Otherwise, create the element.
  if (hasCharactersRemainingElement) {
    const charactersRemainingElement = validationMessageSibling as HTMLElement

    charactersRemainingElement.textContent = buildCharacterCountText(valueLength, limit)

    setTimeout(() => {
      if (liveRegion) {
        liveRegion.textContent = charactersRemainingElement.textContent
      }
    }, SCREEN_READER_UPDATE_DELAY)
    return
  }

  const charactersRemainingElement = document.createElement('span')
  charactersRemainingElement.textContent = buildCharacterCountText(valueLength, limit)
  charactersRemainingElement.className = 'js-ignored-user-note-characters-remaining'
  charactersRemainingElement.id = 'ignored-user-character-count'

  // Add the element after the validation message so the error message is still
  // a direct sibling of the <textarea>, but before the caption
  validationMessage?.after(charactersRemainingElement)
}

onInput('textarea.js-ignored-user-note-field', function (event) {
  const textarea = event.target as HTMLTextAreaElement
  const limit = parseInt(textarea.getAttribute('data-character-limit') || '')

  if (!limit) return
  showRemainingCharacterCount(textarea.value, limit, textarea)
})

// Initialize character count for existing textarea
const initializeCharacterCount = () => {
  const textareaElement: HTMLTextAreaElement | null = document.querySelector('textarea.js-ignored-user-note-field')

  if (textareaElement) {
    const limit = parseInt(textareaElement.getAttribute('data-character-limit') || '')

    if (limit) {
      showRemainingCharacterCount(textareaElement.value, limit, textareaElement)
    }
  }
}

// Run initialization when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeCharacterCount)
} else {
  initializeCharacterCount()
}

// Export for testing
if (typeof window !== 'undefined') {
  interface WindowWithInit extends Window {
    initializeBlockedUsersCharacterCount?: () => void
  }
  ;(window as WindowWithInit).initializeBlockedUsersCharacterCount = initializeCharacterCount
}
